"""Validate JSON files against a simple schema definition.

Schema format:
{
    "type": "object",
    "required": ["name", "age"],
    "properties": {
        "name": {"type": "string", "minLength": 1},
        "age":  {"type": "integer", "minimum": 0, "maximum": 150},
        "email": {"type": "string", "pattern": "^.+@.+\\..+$"},
        "tags":  {"type": "array", "items": {"type": "string"}, "minItems": 0},
        "active": {"type": "boolean"},
        "score":  {"type": "number", "minimum": 0},
        "address": {"type": "object", "properties": {"city": {"type": "string"}}}
    }
}

Supported type keywords: object, array, string, integer, number, boolean, null.
Validation keywords: required, properties, items, minimum, maximum,
                      minLength, maxLength, pattern, minItems, maxItems, enum.
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


class ValidationError:
    """A single validation failure."""

    def __init__(self, path: str, message: str) -> None:
        self.path = path
        self.message = message

    def __repr__(self) -> str:
        return f"ValidationError({self.path!r}, {self.message!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ValidationError):
            return NotImplemented
        return self.path == other.path and self.message == other.message


# ---------------------------------------------------------------------------
# Core validator
# ---------------------------------------------------------------------------

def _validate(value: Any, schema: dict, path: str) -> list[ValidationError]:
    """Recursively validate *value* against *schema*. Returns a list of errors."""
    errors: list[ValidationError] = []
    expected_type = schema.get("type")

    # -- type check ----------------------------------------------------------
    TYPE_MAP = {
        "object": dict,
        "array": list,
        "string": str,
        "integer": int,
        "number": (int, float),
        "boolean": bool,
        "null": type(None),
    }

    if expected_type:
        py_type = TYPE_MAP.get(expected_type)
        if py_type is None:
            errors.append(ValidationError(path, f"unknown type '{expected_type}'"))
            return errors
        if expected_type == "integer" and isinstance(value, bool):
            # bool is a subclass of int; reject it for integer
            errors.append(ValidationError(path, "expected integer, got bool"))
            return errors
        if not isinstance(value, py_type):
            errors.append(
                ValidationError(path, f"expected {expected_type}, got {_type_name(value)}")
            )
            return errors

    # -- object validations ---------------------------------------------------
    if isinstance(value, dict):
        for field in schema.get("required", []):
            if field not in value:
                errors.append(ValidationError(f"{path}.{field}", "required field missing"))
        prop_schemas = schema.get("properties", {})
        for key, val in value.items():
            child_schema = prop_schemas.get(key)
            if child_schema is not None:
                errors.extend(_validate(val, child_schema, f"{path}.{key}"))

    # -- array validations ----------------------------------------------------
    if isinstance(value, list):
        items_schema = schema.get("items")
        if items_schema is not None:
            for i, item in enumerate(value):
                errors.extend(_validate(item, items_schema, f"{path}[{i}]"))
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(ValidationError(path, f"array length {len(value)} < minItems {schema['minItems']}"))
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errors.append(ValidationError(path, f"array length {len(value)} > maxItems {schema['maxItems']}"))

    # -- string validations ---------------------------------------------------
    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(ValidationError(path, f"string length {len(value)} < minLength {schema['minLength']}"))
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(ValidationError(path, f"string length {len(value)} > maxLength {schema['maxLength']}"))
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errors.append(ValidationError(path, f"string does not match pattern '{schema['pattern']}'"))

    # -- numeric validations --------------------------------------------------
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(ValidationError(path, f"{value} < minimum {schema['minimum']}"))
        if "maximum" in schema and value > schema["maximum"]:
            errors.append(ValidationError(path, f"{value} > maximum {schema['maximum']}"))

    # -- enum ----------------------------------------------------------------
    if "enum" in schema and value not in schema["enum"]:
        errors.append(ValidationError(path, f"value {value!r} not in enum {schema['enum']}"))

    return errors


def _type_name(value: Any) -> str:
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    if value is None:
        return "null"
    return type(value).__name__


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def validate(data: Any, schema: dict) -> list[ValidationError]:
    """Validate *data* against *schema*. Returns an empty list on success."""
    return _validate(data, schema, "$")


def validate_file(filepath: str | Path, schema: dict) -> list[ValidationError]:
    """Load JSON from *filepath* and validate it against *schema*."""
    path = Path(filepath)
    with path.open() as f:
        data = json.load(f)
    return validate(data, schema)


def load_schema(filepath: str | Path) -> dict:
    """Load a JSON schema from a file."""
    path = Path(filepath)
    with path.open() as f:
        return json.load(f)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main() -> None:
    import argparse

    parser = argparse.ArgumentParser(description="Validate a JSON file against a schema.")
    parser.add_argument("json_file", help="Path to the JSON file to validate")
    parser.add_argument("schema_file", help="Path to the JSON schema file")
    args = parser.parse_args()

    schema = load_schema(args.schema_file)
    errors = validate_file(args.json_file, schema)

    if errors:
        for err in errors:
            print(f"{err.path}: {err.message}")
        raise SystemExit(1)
    else:
        print("Valid.")


if __name__ == "__main__":
    main()

"""Tests for json_validate.py."""

import json
import tempfile
from pathlib import Path

import pytest

from json_validate import ValidationError, validate, validate_file, load_schema


# ---------------------------------------------------------------------------
# validate() unit tests
# ---------------------------------------------------------------------------

class TestPrimitives:
    def test_string_valid(self):
        assert validate("hello", {"type": "string"}) == []

    def test_string_invalid(self):
        errors = validate(42, {"type": "string"})
        assert len(errors) == 1
        assert "expected string" in errors[0].message

    def test_integer_valid(self):
        assert validate(42, {"type": "integer"}) == []

    def test_integer_rejects_bool(self):
        errors = validate(True, {"type": "integer"})
        assert len(errors) == 1
        assert "integer" in errors[0].message

    def test_number_accepts_int(self):
        assert validate(42, {"type": "number"}) == []

    def test_number_accepts_float(self):
        assert validate(3.14, {"type": "number"}) == []

    def test_boolean_valid(self):
        assert validate(True, {"type": "boolean"}) == []

    def test_null_valid(self):
        assert validate(None, {"type": "null"}) == []

    def test_null_invalid(self):
        errors = validate("x", {"type": "null"})
        assert len(errors) == 1


class TestStringConstraints:
    def test_min_length_pass(self):
        assert validate("abc", {"type": "string", "minLength": 3}) == []

    def test_min_length_fail(self):
        errors = validate("ab", {"type": "string", "minLength": 3})
        assert len(errors) == 1
        assert "minLength" in errors[0].message

    def test_max_length_pass(self):
        assert validate("abc", {"type": "string", "maxLength": 3}) == []

    def test_max_length_fail(self):
        errors = validate("abcd", {"type": "string", "maxLength": 3})
        assert len(errors) == 1

    def test_pattern_pass(self):
        assert validate("a@b.c", {"type": "string", "pattern": r"^.+@.+\..+$"}) == []

    def test_pattern_fail(self):
        errors = validate("not-an-email", {"type": "string", "pattern": r"^.+@.+\..+$"})
        assert len(errors) == 1
        assert "pattern" in errors[0].message


class TestNumericConstraints:
    def test_minimum_pass(self):
        assert validate(10, {"type": "integer", "minimum": 0}) == []

    def test_minimum_fail(self):
        errors = validate(-1, {"type": "integer", "minimum": 0})
        assert len(errors) == 1

    def test_maximum_pass(self):
        assert validate(100, {"type": "integer", "maximum": 150}) == []

    def test_maximum_fail(self):
        errors = validate(200, {"type": "integer", "maximum": 150})
        assert len(errors) == 1


class TestArray:
    def test_valid_array(self):
        schema = {"type": "array", "items": {"type": "string"}}
        assert validate(["a", "b"], schema) == []

    def test_invalid_item_type(self):
        schema = {"type": "array", "items": {"type": "string"}}
        errors = validate(["a", 42], schema)
        assert len(errors) == 1
        assert "$[1]" in errors[0].path

    def test_min_items_pass(self):
        schema = {"type": "array", "minItems": 2}
        assert validate([1, 2], schema) == []

    def test_min_items_fail(self):
        schema = {"type": "array", "minItems": 2}
        errors = validate([1], schema)
        assert len(errors) == 1

    def test_max_items_fail(self):
        schema = {"type": "array", "maxItems": 1}
        errors = validate([1, 2], schema)
        assert len(errors) == 1


class TestObject:
    def test_valid_object(self):
        schema = {
            "type": "object",
            "required": ["name"],
            "properties": {"name": {"type": "string"}},
        }
        assert validate({"name": "Alice"}, schema) == []

    def test_missing_required(self):
        schema = {
            "type": "object",
            "required": ["name"],
            "properties": {"name": {"type": "string"}},
        }
        errors = validate({}, schema)
        assert len(errors) == 1
        assert "required" in errors[0].message

    def test_invalid_property_type(self):
        schema = {
            "type": "object",
            "properties": {"age": {"type": "integer"}},
        }
        errors = validate({"age": "old"}, schema)
        assert len(errors) == 1

    def test_nested_object(self):
        schema = {
            "type": "object",
            "properties": {
                "address": {
                    "type": "object",
                    "properties": {"city": {"type": "string"}},
                }
            },
        }
        errors = validate({"address": {"city": 123}}, schema)
        assert len(errors) == 1
        assert "$.address.city" in errors[0].path

    def test_unknown_properties_ignored(self):
        schema = {"type": "object", "properties": {"x": {"type": "string"}}}
        assert validate({"x": "ok", "extra": 99}, schema) == []


class TestEnum:
    def test_enum_pass(self):
        assert validate("red", {"type": "string", "enum": ["red", "green", "blue"]}) == []

    def test_enum_fail(self):
        errors = validate("yellow", {"type": "string", "enum": ["red", "green", "blue"]})
        assert len(errors) == 1
        assert "enum" in errors[0].message


class TestMultipleErrors:
    def test_collects_all_errors(self):
        schema = {
            "type": "object",
            "required": ["name", "age"],
            "properties": {
                "name": {"type": "string", "minLength": 1},
                "age": {"type": "integer", "minimum": 0},
            },
        }
        errors = validate({"name": ""}, schema)
        messages = [e.message for e in errors]
        assert any("required" in m for m in messages)
        assert any("minLength" in m for m in messages)


# ---------------------------------------------------------------------------
# File I/O tests
# ---------------------------------------------------------------------------

class TestFileValidation:
    def _write_tmp(self, data, suffix=".json") -> Path:
        f = tempfile.NamedTemporaryFile(mode="w", suffix=suffix, delete=False)
        json.dump(data, f)
        f.flush()
        return Path(f.name)

    def test_validate_file_valid(self):
        schema = {
            "type": "object",
            "required": ["x"],
            "properties": {"x": {"type": "integer"}},
        }
        path = self._write_tmp({"x": 1})
        assert validate_file(path, schema) == []

    def test_validate_file_invalid(self):
        schema = {"type": "object", "required": ["x"]}
        path = self._write_tmp({"y": 1})
        errors = validate_file(path, schema)
        assert len(errors) == 1

    def test_load_schema(self):
        schema = {"type": "object", "required": ["a"]}
        path = self._write_tmp(schema, suffix=".schema.json")
        loaded = load_schema(path)
        assert loaded == schema

    def test_roundtrip_file(self):
        schema = {
            "type": "object",
            "required": ["name", "age"],
            "properties": {
                "name": {"type": "string", "minLength": 1},
                "age": {"type": "integer", "minimum": 0, "maximum": 150},
            },
        }
        schema_path = self._write_tmp(schema, suffix=".schema.json")
        data_path = self._write_tmp({"name": "Bob", "age": 30})
        loaded_schema = load_schema(schema_path)
        assert validate_file(data_path, loaded_schema) == []


# ---------------------------------------------------------------------------
# ValidationError repr / eq
# ---------------------------------------------------------------------------

class TestValidationError:
    def test_repr(self):
        e = ValidationError("$.x", "bad")
        assert repr(e) == "ValidationError('$.x', 'bad')"

    def test_eq(self):
        assert ValidationError("$.x", "a") == ValidationError("$.x", "a")

    def test_neq(self):
        assert ValidationError("$.x", "a") != ValidationError("$.y", "a")

    def test_neq_other_type(self):
        assert ValidationError("$.x", "a") != "not an error"
